import { useEffect, useState } from 'react'
import { NavLink } from 'react-router-dom'

import { threePortalApi } from '../../services/apiClient'

export function NotificationBell() {
  const [unread, setUnread] = useState(0)

  useEffect(() => {
    let cancelled = false
    async function poll() {
      try {
        const { data } = await threePortalApi.getNotifications(true)
        if (!cancelled) setUnread(data.length)
      } catch {
        // Non-critical: leave last known count
      }
    }
    void poll()
    const interval = setInterval(poll, 60_000)
    return () => {
      cancelled = true
      clearInterval(interval)
    }
  }, [])

  return (
    <NavLink to="/notifications" className="notification-bell" aria-label={`Notifications, ${unread} unread`}>
      <span aria-hidden="true">🔔</span>
      {unread > 0 && <span className="notification-bell-count">{unread > 9 ? '9+' : unread}</span>}
    </NavLink>
  )
}
